      "fonte_ids": ["CHANGE.D02", "N.SUP_MOTOR"],
      "justificativa": "N.SUP_MOTOR associa SUP_MOTOR à disponibilidade contratada e registra sua restrição local de não iniciar antes de D18. CHANGE.D02 anuncia a nova disponibilidade contratada de SUP_MOTOR, dando suporte à atualização do valor dessa restrição local."
,
      "contexto_ids": []
    },
    "atributo": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02", "N.SUP_MOTOR"],
      "justificativa": "A alteração anunciada é da disponibilidade contratada, atributo que N.SUP_MOTOR distingue da duração da atividade. CHANGE.D02 afirma que as demais durações permanecem mantidas, não que a duração de SUP_MOTOR passe a 25 dias.",
      "contexto_ids": []
    },
    "unidade": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02"],
      "justificativa": "CHANGE.D02 expressa a nova disponibilidade em dias corridos desde D0.",
      "contexto_ids": []
    },
    "valor": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02"],
      "justificativa": "CHANGE.D02 afirma explicitamente que a nova disponibilidade contratada de SUP_MOTOR é de 25 dias corridos desde D0, sustentando o valor proposto para a restrição local.",
